using NovaHarvest.Core.Dialogue;using NovaHarvest.Core.NPC;namespace NovaHarvest.Core.Systems;public sealed class DialogueManager {public Dialogue? CurrentDialogue{get;private set;}public NPC? CurrentNPC{get;private set;}public bool IsActive=>CurrentDialogue?.CurrentNode is not null;public bool Start(NPC npc,Dialogue d){if(IsActive||npc is null||d is null||!d.Start())return false;CurrentNPC=npc;CurrentDialogue=d;return true;}public bool Continue()=>IsActive&&CurrentDialogue!.Continue();public bool Choose(string id){if(!IsActive)return false;var c=CurrentDialogue!.CurrentNode!.Choices.FirstOrDefault(x=>x.Id==id);if(c is null)return false;if(c.FriendshipChange>0)CurrentNPC!.IncreaseFriendship(c.FriendshipChange);else if(c.FriendshipChange<0)CurrentNPC!.DecreaseFriendship(Math.Abs(c.FriendshipChange));return CurrentDialogue.Choose(id);}public void End(){CurrentDialogue=null;CurrentNPC=null;}public DialogueNode? GetCurrentNode()=>CurrentDialogue?.CurrentNode;public IReadOnlyList<DialogueChoice> GetCurrentChoices()=>CurrentDialogue?.CurrentNode?.Choices??Array.Empty<DialogueChoice>();}
